import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        retries = 0
        max_retries = 3
        backoff_times = [0.5, 1.0, 2.0]

        while True:
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                code = e.code
                if code == 429:
                    if retries >= max_retries:
                        raise RateLimitError(f"Rate limited after {max_retries} retries")
                    wait_time = backoff_times[retries]
                    retries += 1
                    time.sleep(wait_time)
                elif 500 <= code < 600:
                    if retries >= 1:
                        raise ServerError(f"Server error {code} after retry")
                    retries += 1
                    time.sleep(1)
                elif 400 <= code < 500:
                    raise ClientError(f"Client error {code}")
                else:
                    raise
            except urllib.error.URLError as e:
                if retries >= 1:
                    raise ConnectionError(f"Connection failed after retry: {e}")
                retries += 1
                time.sleep(1)
            except Exception as e:
                # Re-raise unexpected exceptions immediately
                raise
